#include <Wire.h>
#include <EEPROM.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
#include <RTClib.h>

// --- СОСТОЯНИЯ СИСТЕМЫ ---
enum State {
  STATE_OFF,        // Выключенное состояние (ждет зажатия ВВОД)
  STATE_SET_DAYS,
  STATE_SET_HOURS,
  STATE_SET_MINS,
  STATE_SET_SECS,
  STATE_COUNTDOWN,
  STATE_UNLOCKED
};

// --- НАСТРОЙКИ ДИСПЛЕЯ И RTC ---
#define SCREEN_WIDTH 128
#define SCREEN_HEIGHT 64
Adafruit_SSD1306 display(SCREEN_WIDTH, SCREEN_HEIGHT, &Wire, -1);
RTC_DS1307 rtc; // В реальном железе замените на RTC_DS3231 rtc;

// --- ПИНЫ ---
const int LOCK_PIN      = 3;  // Силовой ключ замка (D3)
const int BTN_UP        = 4;  // Кнопка ВВЕРХ (D4)
const int BTN_DOWN      = 5;  // Кнопка ВНИЗ (D5)
const int BTN_ENTER     = 6;  // Кнопка ВВОД (D6)
const int LIMIT_SWITCH  = 7;  // Концевой датчик крышки (D7 -> GND)
const int BATTERY_PIN   = A0; // Вход делителя напряжения аккумулятора (A0)

// --- АДРЕСА В EEPROM ---
const int EEPROM_MAGIC_ADDR    = 0;   
const int EEPROM_TARGET_ADDR   = 1; // 4 байта Unix timestamp окончания 
const int EEPROM_DURATION_ADDR = 5; // 4 байта общей длительности
const uint8_t MAGIC_BYTE        = 0xAA;   

// --- ТАЙМАУТЫ И УДЕРЖАНИЕ ---
const unsigned long DISPLAY_TIMEOUT_MS = 10000; // 10 сек до сна экрана
const uint32_t GRACE_PERIOD_SEC        = 30;    // 30 сек на отмену таймера
const unsigned long HOLD_TIME_MS       = 2000;  // 2 секунды удержания кнопки для включения

unsigned long lastActivityTime = 0;
bool isDisplayOn = false;

State currentState = STATE_OFF;

// --- ПЕРЕМЕННЫЕ НАСТРОЙКИ ТАЙМЕРА ---
int setDays = 0;
int setHours = 0;
int setMins = 0;
int setSecs = 0;

uint32_t targetUnixTime = 0;
uint32_t totalDurationSec = 0;

// Мигание при настройке
unsigned long lastBlinkMs = 0;
bool blinkState = true;

// ПРОТОТИПЫ ФУНКЦИЙ
void wakeDisplay();
void sleepDisplay();
void openLock();
void updateCountdown();
void checkDisplaySleep();
bool isBoxClosed();
void showCloseBoxWarning();
int getBatteryPercent();
bool isButtonPressed(int pin);
bool isButtonHeld(int pin, unsigned long holdMs);
bool handleSetTime(const char* label, int &value, int minVal, int maxVal, State nextState);

// ----------------------------------------------------
// SETUP
// ----------------------------------------------------
void setup() {
  pinMode(BTN_UP, INPUT_PULLUP);
  pinMode(BTN_DOWN, INPUT_PULLUP);
  pinMode(BTN_ENTER, INPUT_PULLUP);
  pinMode(LIMIT_SWITCH, INPUT_PULLUP);
  pinMode(LOCK_PIN, OUTPUT);
  digitalWrite(LOCK_PIN, LOW);

  Wire.begin();
  display.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  rtc.begin();

  // Изначально выключаем экран
  sleepDisplay();

  currentState = STATE_OFF;
}

// ----------------------------------------------------
// MAIN LOOP
// ----------------------------------------------------
void loop() {
  if (millis() - lastBlinkMs > 400) {
    lastBlinkMs = millis();
    blinkState = !blinkState;
  }

  switch (currentState) {
    case STATE_OFF:
      // Ожидаем зажатия кнопки ВВОД на 2 секунды для включения
      if (isButtonHeld(BTN_ENTER, HOLD_TIME_MS)) {
        wakeDisplay();

        // Показываем приветствие
        display.clearDisplay();
        display.setTextColor(SSD1306_WHITE);
        display.setTextSize(2);
        display.setCursor(20, 20);
        display.print(F("PRIVET!"));
        display.display();
        delay(1500);

        // Проверяем, был ли сохранен активный таймер
        uint8_t magic = EEPROM.read(EEPROM_MAGIC_ADDR);
        if (magic == MAGIC_BYTE) {
          EEPROM.get(EEPROM_TARGET_ADDR, targetUnixTime);
          EEPROM.get(EEPROM_DURATION_ADDR, totalDurationSec);
          DateTime now = rtc.now();

          if (now.unixtime() < targetUnixTime) {
            currentState = STATE_COUNTDOWN;
          } else {
            currentState = STATE_UNLOCKED;
            openLock();
          }
        } else {
          currentState = STATE_SET_DAYS;
        }
      }
      break;

    case STATE_SET_DAYS:
      handleSetTime("DAYS", setDays, 0, 99, STATE_SET_HOURS);
      break;

    case STATE_SET_HOURS:
      handleSetTime("HOURS", setHours, 0, 23, STATE_SET_MINS);
      break;

    case STATE_SET_MINS:
      handleSetTime("MINUTES", setMins, 0, 59, STATE_SET_SECS);
      break;

    case STATE_SET_SECS:
      if (handleSetTime("SECONDS", setSecs, 0, 59, STATE_COUNTDOWN)) {

        // Ждем закрытия крышки (концевика)
        while (!isBoxClosed()) {
          wakeDisplay();
          showCloseBoxWarning();
          delay(100);
        }

        // Запуск таймера
        totalDurationSec = ((uint32_t)setDays * 86400UL) + 
                           ((uint32_t)setHours * 3600UL) + 
                           ((uint32_t)setMins * 60UL) + 
                           setSecs;

        DateTime now = rtc.now();
        targetUnixTime = now.unixtime() + totalDurationSec;

        // Сохраняем в EEPROM
        EEPROM.write(EEPROM_MAGIC_ADDR, MAGIC_BYTE);
        EEPROM.put(EEPROM_TARGET_ADDR, targetUnixTime);
        EEPROM.put(EEPROM_DURATION_ADDR, totalDurationSec);
      }
      break;

    case STATE_COUNTDOWN: {
      DateTime now = rtc.now();
      uint32_t startTimeUnix = (targetUnixTime > totalDurationSec) ? (targetUnixTime - totalDurationSec) : 0;
      uint32_t elapsedSec = (now.unixtime() >= startTimeUnix) ? (now.unixtime() - startTimeUnix) : 9999;

      // Окно отмены (первые 30 секунд)
      if (elapsedSec < GRACE_PERIOD_SEC) {
        wakeDisplay(); // Экран не гаснет в окно отмены
        if (isButtonPressed(BTN_ENTER)) {
          // Отмена таймера
          EEPROM.write(EEPROM_MAGIC_ADDR, 0x00);
          openLock();
          setDays = setHours = setMins = setSecs = 0;
          currentState = STATE_SET_DAYS;
          break;
        }
      } else {
        checkDisplaySleep();
        if (digitalRead(BTN_UP) == LOW || digitalRead(BTN_DOWN) == LOW || digitalRead(BTN_ENTER) == LOW) {
          wakeDisplay();
          delay(200);
        }
      }

      updateCountdown();
      break;
    }

    case STATE_UNLOCKED:
      display.clearDisplay();
      display.setTextSize(2);
      display.setCursor(15, 25);
      display.print(F("OTKRYTO!"));
      display.display();

      wakeDisplay();

      if (isButtonPressed(BTN_ENTER)) {
        EEPROM.write(EEPROM_MAGIC_ADDR, 0x00);
        setDays = setHours = setMins = setSecs = 0;
        currentState = STATE_SET_DAYS;
      }
      break;

    default:
      break;
  }
}

// ----------------------------------------------------
// ПРОВЕРКА УДЕРЖАНИЯ КНОПКИ (ДЛЯ ВКЛЮЧЕНИЯ)
// ----------------------------------------------------
bool isButtonHeld(int pin, unsigned long holdMs) {
  if (digitalRead(pin) == LOW) {
    delay(50); // Дебаунс
    if (digitalRead(pin) == LOW) {
      unsigned long start = millis();
      while (digitalRead(pin) == LOW) {
        if (millis() - start >= holdMs) {
          // Ждем, пока пользователь отпустит кнопку
          while (digitalRead(pin) == LOW);
          return true;
        }
      }
    }
  }
  return false;
}

// ----------------------------------------------------
// ИЗМЕРЕНИЕ ЗАРЯДА АККУМУЛЯТОРА (18650)
// ----------------------------------------------------
int getBatteryPercent() {
  long rawValue = 0;
  for (int i = 0; i < 10; i++) {
    rawValue += analogRead(BATTERY_PIN);
    delay(2);
  }
  rawValue /= 10;

  // Делитель 100кОм + 100кОм (деление на 2)
  float voltage = (rawValue * 5.0 / 1023.0) * 2.0;

  // Для 18650 Li-ion: 3.3V = 0%, 4.2V = 100%
  int percent = map(voltage * 100, 330, 420, 0, 100);

  return constrain(percent, 0, 100);
}

// ----------------------------------------------------
// ВСПОМОГАТЕЛЬНЫЕ ФУНКЦИИ
// ----------------------------------------------------
bool isBoxClosed() {
  return digitalRead(LIMIT_SWITCH) == LOW; // LOW = замкнут = закрыто
}

void showCloseBoxWarning() {
  display.clearDisplay();
  display.setTextSize(2);
  display.setCursor(15, 15);
  display.print(F("ZAKROYTE"));
  display.setCursor(15, 40);
  display.print(F("KOROBKU!"));
  display.display();
}

bool isButtonPressed(int pin) {
  if (digitalRead(pin) == LOW) {
    delay(50);
    if (digitalRead(pin) == LOW) {
      wakeDisplay();
      while (digitalRead(pin) == LOW);
      return true;
    }
  }
  return false;
}

void wakeDisplay() {
  lastActivityTime = millis();
  if (!isDisplayOn) {
    display.ssd1306_command(SSD1306_DISPLAYON);
    isDisplayOn = true;
  }
}

void sleepDisplay() {
  display.ssd1306_command(SSD1306_DISPLAYOFF);
  isDisplayOn = false;
}

void checkDisplaySleep() {
  if (isDisplayOn && (millis() - lastActivityTime > DISPLAY_TIMEOUT_MS)) {
    sleepDisplay();
  }
}

bool handleSetTime(const char* label, int &value, int minVal, int maxVal, State nextState) {
  display.clearDisplay();

  display.setTextSize(1);
  display.setCursor(0, 0);
  display.print(F("SET TIMER"));

  display.setCursor(95, 0);
  display.print(getBatteryPercent());
  display.print(F("%"));

  display.setCursor(0, 15);
  display.print(label);

  display.setTextSize(3);
  display.setCursor(35, 35);

  if (blinkState) {
    if (value < 10) display.print("0");
    display.print(value);
  } else {
    display.print("  ");
  }
  display.display();

  if (isButtonPressed(BTN_UP)) {
    value++;
    if (value > maxVal) value = minVal;
  }
  if (isButtonPressed(BTN_DOWN)) {
    value--;
    if (value < minVal) value = maxVal;
  }
  if (isButtonPressed(BTN_ENTER)) {
    currentState = nextState;
    return true;
  }
  return false;
}

void updateCountdown() {
  DateTime now = rtc.now();

  if (now.unixtime() >= targetUnixTime) {
    openLock();
    currentState = STATE_UNLOCKED;
    return;
  }

  uint32_t remaining = targetUnixTime - now.unixtime();
  uint32_t startTimeUnix = (targetUnixTime > totalDurationSec) ? (targetUnixTime - totalDurationSec) : 0;
  uint32_t elapsedSec = (now.unixtime() >= startTimeUnix) ? (now.unixtime() - startTimeUnix) : 9999;

  uint32_t d = remaining / 86400UL;
  uint32_t h = (remaining % 86400UL) / 3600UL;
  uint32_t m = (remaining % 3600UL) / 60UL;
  uint32_t s = remaining % 60UL;

  if (isDisplayOn) {
    display.clearDisplay();

    display.setTextSize(1);
    display.setCursor(0, 0);
    display.print(F("TIME REMAINING"));

    display.setCursor(95, 0);
    display.print(getBatteryPercent());
    display.print(F("%"));

    display.setTextSize(2);
    display.setCursor(5, 18);

    if (d < 10) display.print("0");
    display.print(d); display.print("d ");

    if (h < 10) display.print("0");
    display.print(h); display.print(":");

    if (m < 10) display.print("0");
    display.print(m); display.print(":");

    if (s < 10) display.print("0");
    display.print(s);

    if (elapsedSec < GRACE_PERIOD_SEC) {
      display.setTextSize(1);
      display.setCursor(5, 48);
      display.print(F("[ENTER] CANCEL: "));
      display.print(GRACE_PERIOD_SEC - elapsedSec);
      display.print(F("s"));
    }

    display.display();
  }
}

void openLock() {
  digitalWrite(LOCK_PIN, HIGH);
  delay(1500);
  digitalWrite(LOCK_PIN, LOW);
  EEPROM.write(EEPROM_MAGIC_ADDR, 0x00);
}
